traceability.evidence:
Story: docs/stories/001.0-DEV-PLUGIN-SETUP.story.md

Implementation and structure:
- src/index.ts is the ESLint plugin entry point and explicitly traces to this story:
  """
  /**
   * ESLint Traceability Plugin
   * @story docs/stories/001.0-DEV-PLUGIN-SETUP.story.md
   * @req REQ-PLUGIN-STRUCTURE - Provide foundational plugin export and registration
   * @req REQ-ERROR-HANDLING - Gracefully handles plugin loading errors and missing dependencies
   */
  import type { Rule } from "eslint";
  ...
  const RULE_NAMES = [
    "require-story-annotation",
    "require-req-annotation",
    "require-branch-annotation",
    "valid-annotation-format",
    "valid-story-reference",
    "valid-req-reference",
  ] as const;

  const rules: Record = {} as any;

  RULE_NAMES.forEach((name) => {
    try {
      const mod = require(`./rules/${name}`);
      rules[name] = mod.default ?? mod;
    } catch (error: any) {
      console.error(
        `[eslint-plugin-traceability] Failed to load rule "${name}": ${error.message}`,
      );
      rules[name] = { ... placeholder RuleModule ... } as Rule.RuleModule;
    }
  });

  const TRACEABILITY_RULE_SEVERITIES = { ... };

  function createTraceabilityFlatConfig() {
    return {
      plugins: {
        traceability: {},
      },
      rules: {
        ...TRACEABILITY_RULE_SEVERITIES,
      },
    };
  }

  const configs = {
    recommended: [createTraceabilityFlatConfig()],
    strict: [createTraceabilityFlatConfig()],
  };

  const maintenance = { ... };

  export { rules, configs, maintenance };
  export default { rules, configs, maintenance };
  """
- This provides a standard ESLint plugin object with a rule registry, configuration presets, and exports, satisfying REQ-PLUGIN-STRUCTURE, REQ-RULE-REGISTRY, REQ-CONFIG-SYSTEM, and REQ-ERROR-HANDLING.

Error handling for plugin/rule loading (REQ-ERROR-HANDLING):
- src/index.ts dynamic loader catches require failures and logs plus installs a placeholder rule:
  """
  } catch (error: any) {
    console.error(
      `[eslint-plugin-traceability] Failed to load rule "${name}": ${error.message}`,
    );
    rules[name] = {
      meta: {
        type: "problem",
        docs: {
          description: `Failed to load rule '${name}'`,
        },
        schema: [],
      },
      create(context: Rule.RuleContext) {
        return {
          Program(node: any) {
            context.report({
              node,
              message: `eslint-plugin-traceability: Error loading rule "${name}": ${error.message}`,
            });
          },
        };
      },
    } as Rule.RuleModule;
  }
  """
- tests/plugin-setup-error.test.ts (tagged to this story and REQ-ERROR-HANDLING) verifies this behavior:
  """
  /**
   * Tests for: docs/stories/001.0-DEV-PLUGIN-SETUP.story.md
   * @story docs/stories/001.0-DEV-PLUGIN-SETUP.story.md
   * @req REQ-ERROR-HANDLING - Gracefully handles plugin loading errors and missing dependencies
   */
  describe("Traceability ESLint Plugin Error Handling (Story 001.0-DEV-PLUGIN-SETUP)", () => {
    beforeEach(() => {
      jest.resetModules();
      jest.spyOn(console, "error").mockImplementation(() => {});
      jest.mock("../src/rules/require-branch-annotation", () => {
        throw new Error("Test load error");
      });
    });

    it("[REQ-ERROR-HANDLING] should report error loading rule and provide placeholder rule", () => {
      const plugin = require("../src/index");
      expect(console.error).toHaveBeenCalledWith(
        expect.stringContaining(
          'Failed to load rule "require-branch-annotation": Test load error',
        ),
      );
      const placeholderRule = plugin.rules["require-branch-annotation"];
      expect(placeholderRule).toBeDefined();
      expect(placeholderRule.meta.docs.description).toContain(
        "Failed to load rule 'require-branch-annotation'",
      );
      const fakeContext = { report: jest.fn() };
      const visitor = placeholderRule.create(fakeContext as any);
      visitor.Program({ type: "Program" });
      expect(fakeContext.report).toHaveBeenCalledWith({
        node: { type: "Program" },
        message: expect.stringContaining(
          'Error loading rule "require-branch-annotation": Test load error',
        ),
      });
    });
  });
  """
- tests/cli-error-handling.test.ts is also tagged with this story and REQ-ERROR-HANDLING, exercising CLI behavior when rules run via ESLint.

