- This confirms that importing the plugin succeeds and rule/config registries are present and wired to the default export.

ESLint v9 flat config integration (Integration AC, REQ-ESLINT-COMPAT):
- eslint.config.js uses ESLint v9 flat-config style and dynamically loads the plugin from src or lib:
  """
  const typescriptParser = require("@typescript-eslint/parser");
  const js = require("@eslint/js");

  let plugin;
  try {
    plugin = require("./src/index.js");
  } catch (eSrc) {
    try {
      plugin = require("./lib/src/index.js");
    } catch (eLib) {
      const inCI = process.env.NODE_ENV === "ci" || process.env.CI === "true";
      if (inCI) {
        throw new Error(
          "Traceability plugin not found. Expected ./src/index.js or ./lib/src/index.js to be present in CI."
        );
      } else {
        console.warn("Traceability plugin not built yet, skipping traceability rules");
        plugin = {};
      }
    }
  }

  module.exports = [
    js.configs.recommended,
    { ... TS config with plugins: { ...(plugin.rules ? { traceability: plugin } : {}) } ... },
    { ... JS config with plugins: { ...(plugin.rules ? { traceability: plugin } : {}) } ... },
    { ... test config ... },
    { ignores: ["lib/**", "node_modules/**", ...] },
  ];
  """
